def find_max_palindromic_cube(N: int) -> int:
    max_palindromic_cube = 0
    upper_limit = int(N ** (1/3)) + 1
    for number in range(1, upper_limit):
        cube = number ** 3
        if cube <= N:
            cube_str = str(cube)
            if cube_str == cube_str[::-1]:
                max_palindromic_cube = max(max_palindromic_cube, cube)
    return max_palindromic_cube
